mapper.select:
select sifg.inventory_flow_id, sifg.goods_id, sifg.goods_num, mgb.goods_name, si.put_storage_id, si.out_storage_id, si.type_details, si.operator_name, si.create_time from storage_inventory_flow_goods sifg left join ${database.prefix.goods}hou_goods_base mgb on mgb.goods_id = sifg.goods_id left join storage_inventory_flow si on si.inventory_flow_id = sifg.inventory_flow_id where sifg.shop_id = #{param.shopId}
and si.type_details = #{param.typeDetails}
and si.create_time between #{param.startTime} and #{param.endTime}
and mgb.goods_name like concat('%',#{param.goodsName},'%')
and si.operator_name like concat('%',#{param.operatorName},'%')
and sifg.inventory_flow_id = #{param.inventoryFlowId}
and (si.put_storage_id in
#{storageId}
or si.out_storage_id in
#{storageId} )
